SELECT email, LENGTH(email) AS chars FROM customers
WHERE LENGTH(email) > 20
ORDER BY chars DESC, email;

SELECT id, ROUND(total * (100 - discount) / 100.0, 2) AS paid FROM orders
WHERE discount IS NOT NULL
ORDER BY paid DESC;

